CALL {
  MATCH (a:Person {name: "Antonio"})-[:KNOWS]->(b:Person {name: "Carolyn"})
  RETURN a
}
WITH DISTINCT a
RETURN count(a)

MATCH (p:Person)-[:HAS_EMAIL]->(e:Email)
WHERE p.surname = "Ford" AND EXISTS {
  MATCH (p)-[:KNOWS]->(f:Person)
  WHERE f.surname = "Cook"
}
RETURN count(e)

MATCH (p1:Person)-[:CURRENT_ADDRESS]->(loc:Location)
WHERE p1.surname = "Cunningham"
AND EXISTS {
  MATCH (p2:Person)-[:KNOWS]->(p1)
  WHERE EXISTS {
    MATCH (p3:Person)-[:PARTY_TO]->(c:Crime)
    WHERE c.date = "19/08/2017"
    AND EXISTS {
      MATCH (p3)-[:HAS_PHONE]->(:Phone)
      MATCH (p2)-[:KNOWS_PHONE]->(p3)
    }
  }
}
RETURN DISTINCT loc.address

